using System;using System.Globalization;using System.Linq;using ForteMove.Models.Operations;using ForteMove.Web.Infrastructure;namespace ForteMove.Web.Driver{public partial class CompleteTrip:DriverPage{private long Id{get{long x;return long.TryParse(Request.QueryString["id"],out x)?x:0;}}protected void Page_Load(object s,EventArgs e){if(!IsPostBack)LoadContext();}private void LoadContext(){var d=ServiceFactory.CreateDriverOperationsService().GetTripDetails(CurrentPrincipalContext.UserAccountId,Id);if(d==null||d.Execution==null){Response.Redirect(ResolveUrl("~/Driver/Today.aspx"),true);return;}litContext.Text=Server.HtmlEncode(d.TripCode+" · "+d.RouteName+" · Bus "+d.FleetNumber);hidTripRv.Value=Convert.ToBase64String(d.TripRowVersion);hidAssignmentRv.Value=Convert.ToBase64String(d.AssignmentRowVersion);hidExecutionRv.Value=Convert.ToBase64String(d.Execution.RowVersion);hidBusRv.Value=Convert.ToBase64String(d.BusRowVersion);txtOdometer.Text=Math.Max(d.BusOdometerKilometres,d.CurrentInspection.StartOdometerKilometres).ToString("0.0",CultureInfo.InvariantCulture);}protected void btnComplete_Click(object s,EventArgs e){decimal x;decimal? odo=decimal.TryParse(txtOdometer.Text,NumberStyles.Number,CultureInfo.InvariantCulture,out x)?x:(decimal?)null;var r=ServiceFactory.CreateDriverOperationsService().CompleteTrip(new CompleteTripRequest{TripId=Id,EndOdometerKilometres=odo,CompletionNote=txtNote.Text,TripRowVersion=Parse(hidTripRv.Value),AssignmentRowVersion=Parse(hidAssignmentRv.Value),RelatedRowVersion=Parse(hidExecutionRv.Value),BusRowVersion=Parse(hidBusRv.Value)},CurrentPrincipalContext.UserAccountId);if(r.Succeeded){Response.Redirect(ResolveUrl("~/Driver/History.aspx"),true);return;}litError.Text=Server.HtmlEncode(string.Join(" ",r.Errors.Select(v=>v.Message)));pnlError.Visible=true;LoadContext();}private static byte[] Parse(string x){try{return Convert.FromBase64String(x);}catch{return null;}}}}
